def get_arithmetic_operation():
    """Get the arithmetic operation from the user."""
    operations = {
        "addition": "+",
        "subtraction": "-",
        "multiplication": "*",
        "division": "/"
    }

    while True:
        operation = input("Enter the arithmetic operation (addition, subtraction, multiplication, or division): ").lower()
        if operation in operations:
            return operation, operations[operation]
        else:
            print("Invalid operation. Please try again.")

def get_numbers():
    """Get two numbers from the user."""
    while True:
        try:
            num1 = float(input("Enter the first number: "))
            num2 = float(input("Enter the second number: "))
            return num1, num2
        except ValueError:
            print("Invalid input. Please enter numbers only.")

def perform_operation(num1, num2, operation, op):
    """Perform the arithmetic operation on the numbers."""
    if op == "+":
        result = num1 + num2
    elif op == "-":
        result = num1 - num2
    elif op == "*":
        result = num1 * num2
    elif op == "/":
        if num2 == 0:
            print("Error: Division by zero is not allowed.")
            return None
        result = num1 / num2
    else:
        print("Error: Invalid operation.")
        return None

    return result

if __name__ == "__main__":
    operation, op = get_arithmetic_operation()
    num1, num2 = get_numbers()

    result = perform_operation(num1, num2, operation, op)

    if result is not None:
        print(f"{num1} {op} {num2} = {result}")
